function is_main() {
  return require.main === module;
}

if (is_main()) {
  const predArity = process.argv[2];
  if (predArity === undefined) {
    process.stdout.write("usage: node generated_program.js <pred>/<arity> <arg> ...\n");
    process.exit(0);
  }
  const startPc = shared_labels[predArity];
  const loweredFn = lowered_dispatch[predArity];
  if (startPc === undefined && typeof loweredFn !== "function") {
    process.stdout.write("unknown predicate: " + predArity + "\n");
    process.exit(1);
  }
  const parsed = [];
  for (let i = 3; i < process.argv.length; i++) {
    parsed.push(Runtime.parse_cli_atom_or_int(shared_program, process.argv[i]));
  }
  const state = Runtime.new_state();
  for (let i = 0; i < parsed.length; i++) Runtime.put_reg(state, i + 1, parsed[i]);
  const slash = String(predArity).lastIndexOf("/");
  const arity = slash >= 0 ? Number(predArity.slice(slash + 1)) : parsed.length;
  for (let i = parsed.length; i < arity; i++) {
    Runtime.put_reg(state, i + 1, Runtime.new_var(state));
  }
  state.program = shared_program;
  const profiling = !!Runtime._prof;
  let ok;
  if (typeof loweredFn === "function") {
    // Dispatch wrapper increments call counts; enter without a second count
    // so exclusive wall time still attributes to this predicate.
    if (profiling) Runtime.prof_enter(predArity, false);
    ok = loweredFn(shared_program, state) === true;
    if (profiling) Runtime.prof_leave();
  } else {
    if (profiling) Runtime.prof_enter(predArity, true);
    state.pc = startPc;
    ok = Runtime.run(shared_program, state) === true;
    if (profiling) Runtime.prof_leave();
  }
  if (profiling) Runtime.profileReport();
  if (ok) {
    const keys = Object.keys(state.regs).map(Number).filter(function (n) { return n >= 1 && n <= 16; }).sort(function (a, b) { return a - b; });
    if (keys.length > 0) {
      for (let i = 0; i < keys.length; i++) {
        const v = Runtime.get_reg(state, keys[i]);
        if (v !== undefined) {
          process.stdout.write("A" + keys[i] + " = " + Runtime.term_to_string(shared_program, state, v) + "\n");
        }
      }
    }
    process.stdout.write("true\n");
    process.exit(0);
  }
  process.stdout.write("false\n");
  process.exit(1);
}

module.exports = M;
